// TestUpsertBatch_RequesttypegroupSearchableViaGenericFTS verifies that a
// dependent-resource row stored via UpsertBatch — the exact path dependent
// sync uses (upsertResourceBatch -> UpsertBatch) — is reachable through the
// generic resources_fts index via Store.Search. That index is the substrate
// both `search` surfaces query (the empty-type search directly, and the
// non-FTS5 `--type requesttypegroup` fallback), so populating it is the
// precondition issue #2629 reported missing — dependent resources stored in
// the typed table but absent from any FTS index. This asserts the store layer
// where the claimed defect lived; it does not exercise the CLI search wiring.
func TestUpsertBatch_RequesttypegroupSearchableViaGenericFTS(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	// resources_fts indexes the full JSON blob, so a distinctive token in any
	// field is matchable regardless of which columns requesttypegroup declares.
	const probe = "zqxjpp2629probe"
	items := []json.RawMessage{
		json.RawMessage(`{"id": "search-001", "pp_fts_probe": "` + probe + `", "servicedesk_id": "parent-A", "parent_id": "parent-A"}`),
	}
	stored, _, err := s.UpsertBatch("requesttypegroup", items)
	if err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}
	// Assert the probe row actually landed before searching for it: a PK
	// extraction miss would leave stored == 0, and the FTS check below would
	// then fail with a misleading "stored but not searchable" message.
	if stored != 1 {
		t.Fatalf("UpsertBatch stored %d rows, want 1 (probe row dropped before the FTS check)", stored)
	}

	results, err := s.Search(probe, 50)
	if err != nil {
		t.Fatalf("Search: %v", err)
	}
	if len(results) == 0 {
		t.Fatalf("dependent resource %q stored but not searchable via generic resources_fts (issue #2629)", "requesttypegroup")
	}
}

// TestUpsertBatch_PopulatesUsageTable verifies that UpsertBatch
// dispatches paginated items into both the generic resources table AND the
// typed usage table. Regression for issue #268: before the fix, paginated
// syncs only filled the generic resources table, so domain commands that
// query the typed table saw zero rows.
func TestUpsertBatch_PopulatesUsageTable(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "test-001"}`),
		json.RawMessage(`{"id": "test-002"}`),
		json.RawMessage(`{"id": "test-003"}`),
	}
	if _, _, err := s.UpsertBatch("usage", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}

	db := s.DB()

	var generic int
	if err := db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, "usage").Scan(&generic); err != nil {
		t.Fatalf("count resources: %v", err)
	}
	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "usage")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count usage: %v", err)
	}
	if typed != len(items) {
		t.Fatalf("usage count = %d, want %d (typed table not populated by UpsertBatch)", typed, len(items))
	}
}
